/**
 * Runtime support for vecDSL programs generated for LanceDB (embedded, open source) with @lancedb/lancedb. Generated by
 * vecDSL 7. Do not edit. The generator builds every table schema, where string, index parameter set and write plan; this
 * module only calls the SDK, converts records to the declared Arrow schema and reports results in one form for every
 * host language.
 */
import { mkdirSync, existsSync, readdirSync, readFileSync, rmdirSync, statSync } from "node:fs";
import { join } from "node:path";
import * as lancedb from "@lancedb/lancedb";
import { Index, MatchQuery, MultiMatchQuery, Operator, PhraseQuery } from "@lancedb/lancedb";
import type { Connection, FullTextQuery, Table } from "@lancedb/lancedb";
import {
  Binary, Bool, DataType, DateDay, Field, FixedSizeList, Float16, Float32, Float64, Int32, Int64, Int8, List, Schema,
  Struct, TimeUnit, Timestamp, Uint8, Utf8,
} from "apache-arrow";

export const SDK_PACKAGE = "{{sdk.typescript.package}}";
export const SDK_VERSION = "{{sdk.typescript.version}}";

const DIGITS = 6;
const BATCH = 1000;

export type Args = Record<string, unknown>;
export type Row = Record<string, unknown>;
type Layout = { name: string; database?: string; key: string; vectors?: Record<string, string> };
type Place = { name: string; database?: string };
type FieldSpec = { name?: string; type: string; nullable?: boolean; dim?: number; bits?: number; element?: any; fields?: FieldSpec[]; metadata?: Record<string, unknown> };
type Plan = Record<string, any>;
type Order = { key: string; direction?: string }[];
type Group = { key: string; size?: number };
type Hit = [Row, number];

export class UnsupportedFeature extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

// ---------------------------------------------------------------- where strings

/** A generated where template with each {name} replaced by the SQL literal of a program parameter. */
export function sql(template: string, values: Record<string, unknown>): string {
  return template.replace(/\{([A-Za-z0-9_]+)(:list)?\}/g, (_match, name: string, list: string | undefined) => {
    const value = values[name];
    if (list) {
      if (!Array.isArray(value) || value.length === 0) {
        throw new Error(`in and not_in need a non-empty list, got ${JSON.stringify(value)}`);
      }
      return "(" + value.map(literal).join(", ") + ")";
    }
    return literal(value);
  });
}

/** The SQL literal of a value: strings in single quotes with quotes doubled, lists as array literals. */
export function literal(value: unknown): string {
  if (value === null || value === undefined) {
    return "NULL";
  }
  if (typeof value === "boolean") {
    return value ? "TRUE" : "FALSE";
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new Error(`cannot use ${value} in a filter`);
    }
    return number(value);
  }
  if (typeof value === "bigint") {
    return value.toString();
  }
  if (typeof value === "string") {
    return "'" + value.replace(/'/g, "''") + "'";
  }
  if (Array.isArray(value)) {
    return "[" + value.map(literal).join(", ") + "]";
  }
  throw new Error(`cannot use ${JSON.stringify(value)} in a filter`);
}

/** Numbers as Python's repr writes them, so that the three runtimes build identical SQL. */
function number(value: number): string {
  if (Number.isInteger(value) && Math.abs(value) < 1e15) {
    return value.toFixed(0);
  }
  const text = String(value);
  if (/e/.test(text)) {
    const [mantissa, exponent] = text.split("e");
    const power = Number(exponent);
    return (mantissa.includes(".") ? mantissa : mantissa + ".0") + "e" + (power < 0 ? "-" : "+") + String(Math.abs(power)).padStart(2, "0");
  }
  return text;
}

export function quote(name: string): string {
  return name.split(".").map((part) => "`" + part.replace(/`/g, "``") + "`").join(".");
}

// ---------------------------------------------------------------- connection

/** The storage URI of the program's database and one connection per logical database (a sub-directory). */
export class Client {
  private readonly connections = new Map<string, Connection>();

  constructor(readonly uri: string, readonly interval: number) {}

  async db(database?: string | null): Promise<Connection> {
    const name = database ?? "";
    let connection = this.connections.get(name);
    if (connection === undefined) {
      const target = name === "" ? this.uri : this.uri.replace(/[/\\]+$/, "") + "/" + name;
      if (!target.includes("://")) {
        mkdirSync(target, { recursive: true });
      }
      connection = await lancedb.connect(target, { readConsistencyInterval: this.interval });
      this.connections.set(name, connection);
    }
    return connection;
  }

  async table(place: Place): Promise<Table> {
    return (await this.db(place.database)).openTable(place.name);
  }

  forget(database: string): void {
    this.connections.get(database)?.close();
    this.connections.delete(database);
  }

  async close(): Promise<void> {
    for (const connection of this.connections.values()) {
      connection.close();
    }
    this.connections.clear();
  }
}

export async function connect(options: { uri: string; interval?: number }): Promise<Client> {
  return new Client(options.uri, options.interval ?? 0);
}

async function names(connection: Connection): Promise<string[]> {
  const result: string[] = [];
  for await (const name of connection.listTables()) {
    result.push(name);
  }
  return result;
}

export async function hasTable(client: Client, args: { table: Place }): Promise<boolean> {
  return (await names(await client.db(args.table.database))).includes(args.table.name);
}

export async function createDatabase(client: Client, args: { database: string }): Promise<void> {
  await client.db(args.database);
}

export async function requireTable(client: Client, args: { table: Place }): Promise<void> {
  if (!(await hasTable(client, args))) {
    throw new Error(`table ${args.table.name} does not exist`);
  }
}

/** Loads the table's indexes into the cache (prewarmData is remote-only in LanceDB OSS, rust/lancedb/src/table.rs); an index that covers no rows yet (created on an empty table) has no files to load. */
export async function loadTable(client: Client, args: { table: Place }): Promise<void> {
  const handle = await client.table(args.table);
  for (const index of await handle.listIndices()) {
    if (((await handle.indexStats(index.name))?.numIndexedRows ?? 0) > 0) {
      await handle.prewarmIndex(index.name);
    }
  }
}

// ---------------------------------------------------------------- schema

const SCALARS: Record<string, () => DataType> = {
  int8: () => new Int8(), int32: () => new Int32(), int64: () => new Int64(), float32: () => new Float32(),
  float64: () => new Float64(), float16: () => new Float16(), uint8: () => new Uint8(), bool: () => new Bool(),
  utf8: () => new Utf8(), binary: () => new Binary(), date: () => new DateDay(),
  timestamp: () => new Timestamp(TimeUnit.MICROSECOND), timestamptz: () => new Timestamp(TimeUnit.MICROSECOND, "UTC"),
};

function arrowType(spec: FieldSpec): DataType {
  const scalar = SCALARS[spec.type];
  if (scalar !== undefined) {
    return scalar();
  }
  switch (spec.type) {
    case "list":
      return new List(arrowField({ name: "item", ...spec.element }));
    case "struct":
      return new Struct((spec.fields ?? []).map(arrowField));
    case "vector":
      return new FixedSizeList(Number(spec.dim), new Field("item", SCALARS[spec.element](), true));
    case "multivector":
      return new List(new Field("item", new FixedSizeList(Number(spec.dim), new Field("item", SCALARS[spec.element](), true)), true));
    default:
      throw new Error(`unknown field type ${spec.type}`);
  }
}

function arrowField(spec: FieldSpec): Field {
  const metadata = new Map(Object.entries(spec.metadata ?? {}).map(([key, value]) => [key, text(value)]));
  return new Field(spec.name ?? "item", arrowType(spec), spec.nullable ?? true, metadata.size > 0 ? metadata : null);
}

function arrowSchema(fields: FieldSpec[]): Schema {
  return new Schema(fields.map(arrowField));
}

function text(value: unknown): string {
  return typeof value === "string" ? value : JSON.stringify(value);
}

function convert(value: unknown, spec: FieldSpec): unknown {
  if (value === null || value === undefined) {
    return null;
  }
  switch (spec.type) {
    case "int64":
      return BigInt(Math.trunc(Number(value)));
    case "date":
    case "timestamp":
    case "timestamptz":
      return typeof value === "string" ? new Date(spec.type === "date" || /[zZ]|[+-]\d\d:\d\d$/.test(value) ? value : value + "Z") : value;
    case "binary":
      return typeof value === "string" ? Buffer.from(value, "utf8") : value;
    case "list":
      return (value as unknown[]).map((item) => convert(item, spec.element));
    case "struct": {
      const record = value as Row;
      return Object.fromEntries((spec.fields ?? []).map((child) => [child.name, convert(record[child.name!], child)]));
    }
    case "vector":
      return spec.bits !== undefined && (value as unknown[]).length !== spec.dim ? pack(value as unknown[]) : (value as unknown[]).map(Number);
    case "multivector":
      return (value as unknown[][]).map((vector) => vector.map(Number));
    default:
      return typeof value === "number" || typeof value === "string" || typeof value === "boolean" ? value : value;
  }
}

/** Records as an Arrow table of the declared schema: defaults for absent fields, slice columns, unknown names rejected. */
function rowsOf(fields: FieldSpec[], rows: Row[], defaults?: Row, slice?: Row) {
  const known = new Map(fields.map((field) => [field.name!, field]));
  const converted = rows.map((row) => {
    const unknown = Object.keys(row).filter((name) => !known.has(name)).sort();
    if (unknown.length > 0) {
      throw new Error(`unknown fields ${unknown.join(", ")}`);
    }
    const record: Row = { ...(defaults ?? {}), ...row, ...(slice ?? {}) };
    return Object.fromEntries([...known].map(([name, field]) => [name, convert(record[name], field)]));
  });
  return lancedb.makeArrowTable(converted, { schema: arrowSchema(fields) });
}

// ---------------------------------------------------------------- DDL

export async function createTable(client: Client, args: { table: Place; schema: FieldSpec[]; indexes?: Plan[]; exist_ok?: boolean }): Promise<void> {
  const connection = await client.db(args.table.database);
  if (args.exist_ok && (await names(connection)).includes(args.table.name)) {
    return;
  }
  const handle = await connection.createEmptyTable(args.table.name, arrowSchema(args.schema));
  for (const index of args.indexes ?? []) {
    await createIndexOn(handle, index);
  }
}

export async function dropTable(client: Client, args: { table: Place; missing_ok?: boolean }): Promise<void> {
  const connection = await client.db(args.table.database);
  if (args.missing_ok && !(await names(connection)).includes(args.table.name)) {
    return;
  }
  await connection.dropTable(args.table.name);
}

/** Drops every table of the logical database and removes its sub-directory when that is left empty. */
export async function dropDatabase(client: Client, args: { database: string }): Promise<void> {
  await (await client.db(args.database)).dropAllTables();
  client.forget(args.database);
  const folder = client.uri.replace(/[/\\]+$/, "") + "/" + args.database;
  if (!folder.includes("://") && existsSync(folder) && readdirSync(folder).length === 0) {
    rmdirSync(folder);
  }
}

export async function listDatabases(client: Client): Promise<string[]> {
  if (client.uri.includes("://")) {
    unsupported("lancedb", "listing logical databases of an object-store URI");
  }
  if (!existsSync(client.uri)) {
    return [];
  }
  return readdirSync(client.uri)
    .filter((name) => !name.endsWith(".lance") && statSync(join(client.uri, name)).isDirectory())
    .sort();
}

async function copy(client: Client, source: Place, target: Place, schema: FieldSpec[], indexes: Plan[], version?: unknown): Promise<Table> {
  const handle = await client.table(source);
  if (version !== undefined && version !== null) {
    await handle.checkout(version as number | string);
  }
  const data = await handle.query().toArrow();
  const created = await (await client.db(target.database)).createTable(target.name, data, { schema: arrowSchema(schema) });
  for (const index of indexes) {
    await createIndexOn(created, index);
  }
  return created;
}

/** LanceDB OSS has no rename: copies rows, schema and declared indexes into the new table, then drops the old one. */
export async function renameTable(client: Client, args: { table: Place; new_name: string; schema: FieldSpec[]; indexes?: Plan[] }): Promise<void> {
  await copy(client, args.table, { ...args.table, name: args.new_name }, args.schema, args.indexes ?? []);
  await (await client.db(args.table.database)).dropTable(args.table.name);
}

/** A shallow clone references the source's files at a version or tag; a full clone copies the rows. */
export async function cloneTable(client: Client, args: { table: Place; target: string; shallow: boolean; schema: FieldSpec[]; indexes?: Plan[]; version?: unknown }): Promise<Row> {
  const connection = await client.db(args.table.database);
  let handle: Table;
  if (args.shallow) {
    const source = await client.table(args.table);
    const options: { sourceVersion?: number; sourceTag?: string } = {};
    if (typeof args.version === "string") {
      options.sourceTag = args.version;
    } else if (args.version !== undefined && args.version !== null) {
      options.sourceVersion = Number(args.version);
    }
    handle = await connection.cloneTable(args.target, await tableUri(client, args.table, source), options);
  } else {
    handle = await copy(client, args.table, { ...args.table, name: args.target }, args.schema, args.indexes ?? [], args.version);
  }
  return { cloned_count: await handle.countRows() };
}

async function tableUri(client: Client, place: Place, _handle: Table): Promise<string> {
  const base = place.database ? client.uri.replace(/[/\\]+$/, "") + "/" + place.database : client.uri;
  return base.replace(/[/\\]+$/, "") + "/" + place.name + ".lance";
}

export async function listTables(client: Client, args: { database?: string; prefix?: string; limit?: number } = {}): Promise<string[]> {
  const all = (await names(await client.db(args.database))).filter((name) => args.prefix === undefined || name.startsWith(args.prefix)).sort();
  return args.limit === undefined ? all : all.slice(0, args.limit);
}

/** New columns: null-filled from their Arrow fields, or computed from generated SQL expressions (defaults), made nullable again for later writes that omit them. */
export async function addColumns(client: Client, args: { table: Place; fields: FieldSpec[]; values?: Record<string, string> }): Promise<void> {
  const handle = await client.table(args.table);
  const plain = args.fields.filter((field) => !(field.name! in (args.values ?? {}))).map(arrowField);
  if (plain.length > 0) {
    await handle.addColumns(plain);
  }
  if (args.values) {
    await handle.addColumns(Object.entries(args.values).map(([name, valueSql]) => ({ name, valueSql })));
    await handle.alterColumns(Object.keys(args.values).map((path) => ({ path, nullable: true })));
  }
}

export async function dropColumns(client: Client, args: { table: Place; names: string[] }): Promise<void> {
  await (await client.table(args.table)).dropColumns(args.names);
}

export async function renameColumn(client: Client, args: { table: Place; name: string; new_name: string }): Promise<void> {
  await (await client.table(args.table)).alterColumns([{ path: args.name, rename: args.new_name }]);
}

/** Collection properties live in the metadata of the key column (LanceDB tables have no table-level properties). */
export async function setMetadata(client: Client, args: { table: Layout; metadata: Record<string, unknown> }): Promise<void> {
  const metadata = Object.fromEntries(Object.entries(args.metadata).map(([key, value]) => [key, text(value)]));
  await (await client.table(args.table)).updateFieldMetadata([{ path: args.table.key, metadata }]);
}

function indexConfig(index: Plan): Index {
  const options: Record<string, unknown> = {};
  if (index.metric) {
    options.distanceType = index.metric;
  }
  for (const [option, name] of [["num_partitions", "numPartitions"], ["num_sub_vectors", "numSubVectors"], ["num_bits", "numBits"],
    ["m", "m"], ["ef_construction", "efConstruction"], ["sample_rate", "sampleRate"], ["max_iterations", "maxIterations"]]) {
    if (option in index) {
      options[name] = Number(index[option]);
    }
  }
  switch (index.kind) {
    case "btree":
      return Index.btree();
    case "bitmap":
      return Index.bitmap();
    case "label_list":
      return Index.labelList();
    case "fts": {
      const fts: Record<string, unknown> = {};
      for (const [option, name] of [["base_tokenizer", "baseTokenizer"], ["language", "language"], ["stem", "stem"],
        ["remove_stop_words", "removeStopWords"], ["lower_case", "lowercase"], ["ascii_folding", "asciiFolding"],
        ["with_position", "withPosition"], ["max_token_length", "maxTokenLength"], ["ngram_min_length", "ngramMinLength"],
        ["ngram_max_length", "ngramMaxLength"], ["prefix_only", "prefixOnly"]]) {
        if (option in index) {
          fts[name] = index[option];
        }
      }
      return Index.fts(fts);
    }
    case "ivf_flat":
      return Index.ivfFlat(options);
    case "ivf_pq":
      return Index.ivfPq(options);
    case "ivf_rq":
      return Index.ivfRq(options);
    case "ivf_hnsw_sq":
      return Index.hnswSq(options);
    case "ivf_hnsw_pq":
      return Index.hnswPq(options);
    default:
      throw new Error(`unknown index kind ${index.kind}`);
  }
}

async function createIndexOn(handle: Table, index: Plan): Promise<void> {
  await handle.createIndex(index.column, { config: indexConfig(index), replace: true, name: index.name });
}

export async function createIndex(client: Client, args: { table: Place; index: Plan }): Promise<void> {
  await createIndexOn(await client.table(args.table), args.index);
}

export async function dropIndex(client: Client, args: { table: Place; name: string }): Promise<void> {
  await (await client.table(args.table)).dropIndex(args.name);
}

/** Retrains the index over every row: createIndex with replace. */
export async function rebuildIndex(client: Client, args: { table: Place; index: Plan }): Promise<void> {
  await createIndexOn(await client.table(args.table), args.index);
}

export async function awaitIndex(client: Client, args: { table: Place; name: string; timeout?: number }): Promise<Row> {
  const handle = await client.table(args.table);
  await handle.waitForIndex([args.name], args.timeout ?? 300);
  const stats = await handle.indexStats(args.name);
  return { index: args.name, indexed_rows: stats?.numIndexedRows ?? 0, unindexed_rows: stats?.numUnindexedRows ?? 0 };
}

export async function listIndexes(client: Client, args: { table: Place; prefix?: string; limit?: number }): Promise<string[]> {
  const all = (await (await client.table(args.table)).listIndices()).map((index) => index.name)
    .filter((name) => args.prefix === undefined || name.startsWith(args.prefix)).sort();
  return args.limit === undefined ? all : all.slice(0, args.limit);
}

/** Compacts small files, prunes nothing (old versions stay for time travel) and adds new rows to every index. */
const SCALAR: Record<string, () => Index> = { BTree: () => Index.btree(), Bitmap: () => Index.bitmap(), LabelList: () => Index.labelList() };

/**
 * Compacts small files, removes untagged versions older than seven days (LanceDB's default; tagged versions stay) and
 * adds new rows to every index. Lance 14.0.2
 * cannot add rows to a scalar index on a nested column that was created on an empty table (it looks the leaf name up as a
 * top-level column, rust/lance/src/index/scalar.rs), so such indexes are rebuilt over the rows first.
 */
export async function optimize(client: Client, args: { table: Place }): Promise<void> {
  const handle = await client.table(args.table);
  if ((await handle.countRows()) > 0) {
    for (const index of await handle.listIndices()) {
      const nested = index.columns[0];
      const config = SCALAR[index.indexType];
      if (config && nested.includes(".") && ((await handle.indexStats(index.name))?.numIndexedRows ?? 0) === 0) {
        await handle.createIndex(nested, { config: config(), replace: true, name: index.name });
      }
    }
  }
  await handle.optimize();
}

export async function describe(client: Client, args: { table: Layout; stats?: boolean; index_progress?: boolean }): Promise<Row> {
  const handle = await client.table(args.table);
  const schema = await handle.schema();
  const indexes = await handle.listIndices();
  const result: Row = {
    name: args.table.name,
    fields: schema.fields.map((field) => ({ name: field.name, type: typeName(field.type), nullable: field.nullable })),
    indexes: indexes.map((index) => index.name).sort(),
  };
  const key = schema.fields.find((field) => field.name === args.table.key);
  for (const [name, value] of [...(key?.metadata ?? new Map<string, string>())].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
    result[name] = value;
  }
  if (args.stats) {
    result.rows = await handle.countRows();
    result.version = await handle.version();
  }
  if (args.index_progress) {
    const progress: Row = {};
    for (const index of indexes) {
      const stats = await handle.indexStats(index.name);
      progress[index.name] = { indexed_rows: stats?.numIndexedRows ?? 0, unindexed_rows: stats?.numUnindexedRows ?? 0 };
    }
    result.index_progress = progress;
  }
  return result;
}

/** Arrow type names as pyarrow writes them, so that describe agrees across languages. */
function typeName(type: DataType): string {
  if (type instanceof FixedSizeList) {
    return `fixed_size_list<item: ${typeName(type.children[0].type)}>[${type.listSize}]`;
  }
  if (type instanceof List) {
    return `list<item: ${typeName(type.children[0].type)}>`;
  }
  if (type instanceof Struct) {
    return `struct<${type.children.map((child) => `${child.name}: ${typeName(child.type)}`).join(", ")}>`;
  }
  const names: Record<string, string> = {
    Int8: "int8", Int32: "int32", Int64: "int64", Float16: "halffloat", Float32: "float", Float64: "double", Uint8: "uint8",
    Bool: "bool", Utf8: "string", LargeUtf8: "large_string", Binary: "binary", LargeBinary: "large_binary", DateDay: "date32[day]",
  };
  if (DataType.isFloat(type)) {
    return ["halffloat", "float", "double"][type.precision];
  }
  if (type instanceof Timestamp) {
    return type.timezone ? `timestamp[us, tz=${type.timezone}]` : "timestamp[us]";
  }
  const constructorName = type.constructor.name;
  return names[constructorName] ?? String(type).toLowerCase();
}

// ---------------------------------------------------------------- versions

/** Tags the current version; without a name the tag is v<version>. */
export async function createTag(client: Client, args: { table: Place; tag?: string }): Promise<Row> {
  const handle = await client.table(args.table);
  const current = await handle.version();
  const tag = args.tag ?? `v${current}`;
  await (await handle.tags()).create(tag, current);
  return { snapshot: tag, version: current };
}

/** Checks out the tagged version and commits it as the newest version (time travel, then restore). */
export async function restoreTag(client: Client, args: { table: Place; tag: string }): Promise<Row> {
  const handle = await client.table(args.table);
  await handle.checkout(args.tag);
  await handle.restore();
  return { restored_count: await handle.countRows() };
}

export async function dropTag(client: Client, args: { table: Place; tag: string }): Promise<void> {
  await (await (await client.table(args.table)).tags()).delete(args.tag);
}

export async function listTags(client: Client, args: { table: Place; prefix?: string; limit?: number }): Promise<string[]> {
  const all = Object.keys(await (await (await client.table(args.table)).tags()).list())
    .filter((name) => args.prefix === undefined || name.startsWith(args.prefix)).sort();
  return args.limit === undefined ? all : all.slice(0, args.limit);
}

export async function listVersions(client: Client, args: { table: Place }): Promise<number[]> {
  return (await (await client.table(args.table)).listVersions()).map((entry) => entry.version);
}

/** The table at its latest version, or checked out at a version number or tag (time travel, read only). */
async function read(client: Client, place: Place, version?: unknown): Promise<Table> {
  const handle = await client.table(place);
  if (version !== undefined && version !== null) {
    await handle.checkout(version as number | string);
  }
  return handle;
}

// ---------------------------------------------------------------- writes

function keyOf(value: unknown): unknown {
  return typeof value === "bigint" ? Number(value) : value;
}

function keyList(table: Layout, keys: unknown[]): string {
  return `${quote(table.key)} IN (${keys.map((key) => literal(keyOf(key))).join(", ")})`;
}

type WriteArgs = { table: Layout; schema: FieldSpec[]; rows: Row[]; defaults?: Row; slice?: Row; batch_size?: number };

/**
 * Inserts records keyed by the primary key: a merge insert that only inserts, after a check for existing keys
 * (on-conflict error), or that also updates matches (update, replace); LanceDB itself has no primary-key constraint.
 */
export async function insert(client: Client, args: WriteArgs & { on_conflict?: string }): Promise<Row> {
  const handle = await client.table(args.table);
  const size = args.batch_size ?? BATCH;
  const conflict = args.on_conflict ?? "error";
  let total = 0;
  for (let start = 0; start < args.rows.length; start += size) {
    const batch = args.rows.slice(start, start + size);
    const keys = batch.map((row) => row[args.table.key]);
    if (new Set(keys.map((key) => JSON.stringify(key))).size !== keys.length) {
      throw new Error(`duplicate keys in one insert into ${args.table.name}`);
    }
    if (conflict === "error") {
      const existing = await handle.countRows(keyList(args.table, keys));
      if (existing > 0) {
        throw new Error(`${existing} of the keys already exist in ${args.table.name}`);
      }
    }
    let builder = handle.mergeInsert(args.table.key);
    if (conflict === "update" || conflict === "replace") {
      builder = builder.whenMatchedUpdateAll();
    }
    const result = await builder.whenNotMatchedInsertAll().execute(rowsOf(args.schema, batch, args.defaults, args.slice));
    total += result.numInsertedRows + result.numUpdatedRows;
  }
  return { insert_count: total };
}

export async function upsert(client: Client, args: WriteArgs): Promise<Row> {
  const handle = await client.table(args.table);
  const size = args.batch_size ?? BATCH;
  let total = 0;
  for (let start = 0; start < args.rows.length; start += size) {
    const data = rowsOf(args.schema, args.rows.slice(start, start + size), args.defaults, args.slice);
    const result = await handle.mergeInsert(args.table.key).whenMatchedUpdateAll().whenNotMatchedInsertAll().execute(data);
    total += result.numInsertedRows + result.numUpdatedRows;
  }
  return { upsert_count: total };
}

/** Records of a local JSON array or JSON Lines file (file:// URIs and paths). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Row[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const content = readFileSync(path, "utf8");
  if (content.trimStart().startsWith("[")) {
    return JSON.parse(content) as Row[];
  }
  return content.split(/\r?\n/).filter((line) => line.trim() !== "").map((line) => JSON.parse(line) as Row);
}

export async function importFile(client: Client, args: Omit<WriteArgs, "rows"> & { location: string; on_conflict?: string }): Promise<Row> {
  const rows = await readRecords(client, { location: args.location });
  const result = await insert(client, { ...args, rows });
  return { import_count: result.insert_count };
}

/** An UPDATE with generated SQL expressions (literals, array_concat, array_remove_all) on the rows of a where string. */
export async function update(client: Client, args: { table: Layout; where: string; values: Record<string, string> }): Promise<Row> {
  const result = await (await client.table(args.table)).update({ where: args.where, valuesSql: args.values });
  return { update_count: result.rowsUpdated };
}

async function existing(handle: Table, where: string, columns: string[]): Promise<Row[]> {
  return (await handle.query().where(where).select(columns).toArray()).map((row) => plainRow(row));
}

/** Update mode replace: every matching record is rewritten with the given values and nulls (or defaults) elsewhere; vectors and slice columns are kept. */
export async function replaceRows(client: Client, args: { table: Layout; schema: FieldSpec[]; where: string; values: Row; defaults?: Row }): Promise<Row> {
  const handle = await client.table(args.table);
  const kept = [args.table.key, ...args.schema.filter((field) => field.type === "vector" || field.type === "multivector" || field.name!.startsWith("vecdsl_"))
    .map((field) => field.name!)];
  const found = await existing(handle, args.where, kept);
  if (found.length === 0) {
    return { update_count: 0 };
  }
  const rows = found.map((row) => ({ ...Object.fromEntries(kept.map((name) => [name, row[name]])), ...args.values }));
  await handle.mergeInsert(args.table.key).whenMatchedUpdateAll().execute(rowsOf(args.schema, rows, args.defaults));
  return { update_count: found.length };
}

/** Vector, list and struct values: the matching rows are read, changed and written back by a merge insert on the key. */
export async function patchRows(client: Client, args: { table: Layout; schema: FieldSpec[]; where: string; values: Row }): Promise<Row> {
  const handle = await client.table(args.table);
  const columns = args.schema.map((field) => field.name!);
  const found = await existing(handle, args.where, columns);
  if (found.length === 0) {
    return { update_count: 0 };
  }
  const rows = found.map((row) => ({ ...Object.fromEntries(columns.map((name) => [name, row[name]])), ...args.values }));
  const result = await handle.mergeInsert(args.table.key).whenMatchedUpdateAll().execute(rowsOf(args.schema, rows));
  return { update_count: result.numUpdatedRows };
}

/** Update from records: a merge insert that updates the matching keys (optionally only rows of a where string). */
export async function updateFrom(client: Client, args: { table: Layout; schema: FieldSpec[]; rows: Row[]; where?: string }): Promise<Row> {
  const handle = await client.table(args.table);
  const keys = args.rows.map((row) => row[args.table.key]);
  if (keys.length === 0) {
    return { update_count: 0 };
  }
  const columns = args.schema.map((field) => field.name!);
  const current = new Map((await existing(handle, keyList(args.table, keys), columns)).map((row) => [JSON.stringify(keyOf(row[args.table.key])), row]));
  const rows = args.rows.map((row) => ({ ...(current.get(JSON.stringify(keyOf(row[args.table.key]))) ?? {}), ...row }));
  const builder = args.where ? handle.mergeInsert(args.table.key).whenMatchedUpdateAll({ where: args.where }) : handle.mergeInsert(args.table.key).whenMatchedUpdateAll();
  const result = await builder.execute(rowsOf(args.schema, rows));
  return { update_count: result.numUpdatedRows };
}

/** The distinct values of a slice column (tenants, namespaces, partitions), sorted. */
export async function listValues(client: Client, args: { table: Layout; column: string; prefix?: string; limit?: number }): Promise<string[]> {
  const handle = await client.table(args.table);
  const rows = await handle.query().select([args.column]).toArray();
  const values = [...new Set(rows.map((row) => row[args.column] as string | null).filter((value): value is string =>
    value !== null && value !== undefined && (args.prefix === undefined || value.startsWith(args.prefix))))].sort();
  return args.limit === undefined ? values : values.slice(0, args.limit);
}

/** Deletes the rows of a where string; a limit deletes the first rows in key order (LanceDB's delete has no limit). */
export async function delete_(client: Client, args: { table: Layout; where: string; limit?: number }): Promise<Row> {
  const handle = await client.table(args.table);
  let where = args.where;
  if (args.limit !== undefined) {
    const keys = (await existing(handle, where, [args.table.key])).map((row) => row[args.table.key]).sort(compare).slice(0, args.limit);
    if (keys.length === 0) {
      return { delete_count: 0 };
    }
    where = keyList(args.table, keys);
  }
  const result = await handle.delete(where);
  return { delete_count: result.numDeletedRows };
}

export { delete_ as delete };

export async function truncate(client: Client, args: { table: Layout; where?: string }): Promise<Row> {
  return delete_(client, { table: args.table, where: args.where ?? "true" });
}

// ---------------------------------------------------------------- reads

/** Arrow values as plain JSON values: vectors and lists as arrays, int64 as numbers, dates as ISO strings. */
function plain(item: unknown): unknown {
  if (item === null || item === undefined) {
    return null;
  }
  if (typeof item === "bigint") {
    return Number(item);
  }
  if (item instanceof Date) {
    return item.toISOString().replace("Z", "").replace(/\.000$/, "");
  }
  if (item instanceof Uint8Array && !(item instanceof Buffer)) {
    return Buffer.from(item).toString("utf8");
  }
  if (ArrayBuffer.isView(item)) {
    return Array.from(item as unknown as ArrayLike<number>, (value) => (typeof value === "bigint" ? Number(value) : value));
  }
  if (Array.isArray(item)) {
    return item.map(plain);
  }
  if (typeof item === "object") {
    const candidate = item as { toArray?: () => unknown; toJSON?: () => unknown };
    if (typeof candidate.toJSON === "function" && !(item.constructor === Object)) {
      return plain(candidate.toJSON());
    }
    return Object.fromEntries(Object.entries(item as Row).map(([key, inner]) => [key, plain(inner)]));
  }
  return item;
}

function plainRow(row: unknown): Row {
  return plain(row) as Row;
}

/** Result values in one form for every host language: floats rounded to six decimals, integral floats as integers. */
function value(item: unknown): unknown {
  if (typeof item === "number") {
    if (!Number.isFinite(item)) {
      return null;
    }
    const rounded = Number(item.toFixed(DIGITS));
    return rounded === 0 ? 0 : rounded;
  }
  if (Array.isArray(item)) {
    return item.map(value);
  }
  if (item !== null && typeof item === "object") {
    return Object.fromEntries(Object.entries(item).map(([key, inner]) => [key, value(inner)]));
  }
  return item;
}

function compare(a: unknown, b: unknown): number {
  const rank = (item: unknown) => (item === null || item === undefined ? 2 : typeof item === "number" ? 0 : 1);
  if (rank(a) !== rank(b)) {
    return rank(a) - rank(b);
  }
  if (typeof a === "number" && typeof b === "number") {
    return a - b;
  }
  const left = String(a);
  const right = String(b);
  return left < right ? -1 : left > right ? 1 : 0;
}

/** Canonical similarity of LanceDB's _distance: l2 is the squared Euclidean distance, cosine 1 - cos, dot 1 - x.y. */
export function similarity(metric: string, distance: number): number {
  if (metric === "l2") {
    return -Math.sqrt(Math.max(distance, 0));
  }
  if (metric === "hamming") {
    return -distance;
  }
  return 1 - distance;
}

function within(score: number, min?: number, max?: number): boolean {
  return (min === undefined || score >= min - 1e-9) && (max === undefined || score <= max + 1e-9);
}

function columnsOf(table: Layout, output: string[], vectors: boolean | string[] | undefined, order?: Order, group?: Group): string[] {
  const columns = [table.key, ...output.filter((name) => name !== table.key)];
  const extra = vectors === true ? Object.keys(table.vectors ?? {}) : Array.isArray(vectors) ? vectors : [];
  for (const name of extra) {
    if (!columns.includes(name)) {
      columns.push(name);
    }
  }
  for (const clause of order ?? []) {
    const root = clause.key.split(".")[0];
    if (clause.key !== "score" && !columns.includes(root)) {
      columns.push(root);
    }
  }
  if (group && !columns.includes(group.key.split(".")[0])) {
    columns.push(group.key.split(".")[0]);
  }
  return columns;
}

function record(table: Layout, row: Row, columns: string[], score?: number): Row {
  const result: Row = { id: value(row[table.key]) };
  if (score !== undefined) {
    result.score = value(score);
  }
  for (const name of columns) {
    if (name !== table.key) {
      result[name] = value(row[name] ?? null);
    }
  }
  return result;
}

function path(row: Row, key: string): unknown {
  let current: unknown = row;
  for (const part of key.split(".")) {
    current = current !== null && typeof current === "object" ? (current as Row)[part] : null;
  }
  return current ?? null;
}

/** Stable sorts by the sort clauses, last clause first; nulls last in both directions. */
function ordered<T>(items: T[], order: Order | undefined, get: (item: T, key: string) => unknown): T[] {
  let result = items;
  for (const clause of [...(order ?? [])].reverse()) {
    const descending = clause.direction === "desc";
    const present = result.filter((item) => get(item, clause.key) !== null);
    const missing = result.filter((item) => get(item, clause.key) === null);
    present.sort((a, b) => (descending ? -1 : 1) * compare(value(get(a, clause.key)), value(get(b, clause.key))));
    result = [...present, ...missing];
  }
  return result;
}

function page(table: Layout, hits: Hit[], shown: string[], limit: number, offset: number | undefined, min?: number, max?: number, order?: Order,
  group?: Group): Row[] {
  if (group) {
    return groups(table, hits, shown, limit, offset, min, max, group);
  }
  let window = hits.filter(([, score]) => within(score, min, max)).slice(0, (offset ?? 0) + limit);
  window = ordered(window, order, (hit, key) => (key === "score" ? hit[1] : path(hit[0], key)));
  return window.slice(offset ?? 0).map(([row, score]) => record(table, row, shown, score));
}

/**
 * Hits grouped by the value of the group key: the groups whose best hit ranks highest (offset and limit count groups), each with
 * its best `size` hits within the score bounds; a group left without a hit is dropped.
 */
function groups(table: Layout, hits: Hit[], shown: string[], limit: number, offset: number | undefined, min: number | undefined,
  max: number | undefined, group: Group): Row[] {
  const members = new Map<string, Hit[]>();
  for (const hit of hits) {
    const key = JSON.stringify(value(path(hit[0], group.key)));
    members.set(key, [...(members.get(key) ?? []), hit]);
  }
  const result: Row[] = [];
  for (const key of [...members.keys()].slice(offset ?? 0, (offset ?? 0) + limit)) {
    const kept = members.get(key)!.slice(0, Number(group.size ?? 1)).filter(([, score]) => within(score, min, max));
    if (kept.length > 0) {
      result.push({ group: value(path(kept[0][0], group.key)), hits: kept.map(([row, score]) => record(table, row, shown, score)) });
    }
  }
  return result;
}

/** Candidates a search ranks: limit plus offset, or every row the where string selects when the hits are grouped. */
async function windowOf(client: Client, table: Layout, where: string | undefined, limit: number, offset: number | undefined,
  group: Group | undefined, version: unknown): Promise<number> {
  return group ? Math.max(await count(client, { table, where, version }), 1) : limit + (offset ?? 0);
}

function byScore(table: Layout) {
  return (a: Hit, b: Hit) => b[1] - a[1] || compare(value(a[0][table.key]), value(b[0][table.key]));
}

/** A binary vector of 0 and 1 values packed into bytes, most significant bit first (numpy.packbits order). */
export function pack(bits: unknown[]): number[] {
  const result: number[] = [];
  for (let start = 0; start < bits.length; start += 8) {
    const chunk = bits.slice(start, start + 8);
    let byte = 0;
    for (const bit of chunk) {
      byte = (byte << 1) | (Number(bit) ? 1 : 0);
    }
    result.push(byte << (8 - chunk.length));
  }
  return result;
}

async function nearest(client: Client, table: Layout, plan: Plan, vector: unknown, limit: number, columns: string[], version?: unknown): Promise<[Row, number, number][]> {
  const handle = await read(client, table, version);
  const key = plan.bits ? Uint8Array.from(pack(vector as unknown[])) : (vector as number[]);
  let query = handle.vectorSearch(key).column(plan.column).distanceType(plan.metric).limit(limit);
  if (plan.where) {
    query = query.where(plan.where);
    if (plan.prefilter === false) {
      query = query.postfilter();
    }
  }
  if (plan.exact) {
    query = query.bypassVectorIndex();
  }
  if ("nprobes" in plan) {
    query = query.nprobes(Number(plan.nprobes));
  }
  if ("refine_factor" in plan) {
    query = query.refineFactor(Number(plan.refine_factor));
  }
  if ("ef" in plan) {
    query = query.ef(Number(plan.ef));
  }
  const rows = (await query.select(columns).toArray()).map(plainRow);
  const queries = plan.multivector ? (vector as unknown[]).length : 0;
  const scored = rows.map((row): [Row, number, number] => {
    const distance = Number(row._distance);
    return [row, plan.multivector ? queries - distance : similarity(plan.metric, distance), distance];
  });
  return scored.sort((a, b) => b[1] - a[1] || compare(value(a[0][table.key]), value(b[0][table.key])));
}

export async function vectorSearch(client: Client, args: { table: Layout; plan: Plan; vector: unknown; limit: number; output: string[];
  offset?: number; score_min?: number; score_max?: number; native?: boolean; vectors?: boolean | string[]; order?: Order; version?: unknown;
  group?: Group }): Promise<Row[]> {
  const columns = columnsOf(args.table, args.output, args.vectors, args.order, args.group);
  const window = await windowOf(client, args.table, args.plan.where, args.limit, args.offset, args.group, args.version);
  const hits = await nearest(client, args.table, args.plan, args.vector, window, columns, args.version);
  const ranked = hits.map(([row, score, distance]): Hit => [row, args.native ? distance : score]);
  return page(args.table, ranked, columnsOf(args.table, args.output, args.vectors), args.limit, args.offset, args.score_min, args.score_max, args.order,
    args.group);
}

export async function lookupVector(client: Client, args: { table: Layout; column: string; id: unknown }): Promise<unknown> {
  const rows = await (await client.table(args.table)).query().where(keyList(args.table, [args.id])).select([args.column]).limit(1).toArray();
  if (rows.length === 0) {
    throw new Error(`record ${JSON.stringify(args.id)} not found in ${args.table.name}`);
  }
  return plain(rows[0][args.column]);
}

function textQuery(plan: Plan, query: string): FullTextQuery {
  const columns = plan.columns as string[];
  const operator = plan.operator === "and" ? Operator.And : Operator.Or;
  const boosts = (plan.boosts ?? {}) as Record<string, number>;
  if (plan.kind === "phrase") {
    if (columns.length !== 1) {
      unsupported("lancedb", "a phrase query over several fields");
    }
    return new PhraseQuery(query, columns[0], { slop: Number(plan.slop ?? 0) });
  }
  if (columns.length === 1) {
    return new MatchQuery(query, columns[0], { boost: Number(boosts[columns[0]] ?? 1), fuzziness: Number(plan.fuzziness ?? 0), operator });
  }
  return new MultiMatchQuery(query, columns, { boosts: columns.map((column) => Number(boosts[column] ?? 1)), operator });
}

async function matches(client: Client, table: Layout, plan: Plan, query: string, limit: number, columns: string[], version?: unknown): Promise<Hit[]> {
  const handle = await read(client, table, version);
  let search = handle.query().fullTextSearch(textQuery(plan, query)).limit(limit);
  if (plan.where) {
    if (plan.prefilter === false) {
      unsupported("lancedb", "post_filter on a keyword search; the TypeScript SDK's full-text Query has no postfilter (VectorQuery has)");
    }
    search = search.where(plan.where);
  }
  const rows = (await search.select(columns).toArray()).map(plainRow);
  return rows.map((row): Hit => [row, Number(row._score)]).sort(byScore(table));
}

export async function keywordSearch(client: Client, args: { table: Layout; plan: Plan; text: string; limit: number; output: string[];
  offset?: number; score_min?: number; score_max?: number; vectors?: boolean | string[]; order?: Order; version?: unknown; group?: Group }): Promise<Row[]> {
  const columns = columnsOf(args.table, args.output, args.vectors, args.order, args.group);
  const window = await windowOf(client, args.table, args.plan.where, args.limit, args.offset, args.group, args.version);
  const hits = await matches(client, args.table, args.plan, args.text, window, columns, args.version);
  return page(args.table, hits, columnsOf(args.table, args.output, args.vectors), args.limit, args.offset, args.score_min, args.score_max, args.order,
    args.group);
}

/** Contribution of one leg: 1/(k + rank), weight * similarity, or weight * min-max normalized score. */
function contribution(fusion: string, k: number, weight: number, ranked: [string, number][]): Map<string, number> {
  const result = new Map<string, number>();
  if (fusion === "rrf") {
    ranked.forEach(([key], index) => result.set(key, 1 / (k + index + 1)));
    return result;
  }
  if (fusion === "weighted") {
    ranked.forEach(([key, score]) => result.set(key, weight * score));
    return result;
  }
  const scores = ranked.map(([, score]) => score);
  const low = scores.length ? Math.min(...scores) : 0;
  const high = scores.length ? Math.max(...scores) : 0;
  ranked.forEach(([key, score]) => result.set(key, weight * (high > low ? (score - low) / (high - low) : 1)));
  return result;
}

export async function hybridSearch(client: Client, args: { table: Layout; legs: Plan[]; limit: number; fusion: string; output: string[]; k?: number;
  offset?: number; score_min?: number; score_max?: number; vectors?: boolean | string[]; order?: Order; version?: unknown; group?: Group }): Promise<Row[]> {
  const columns = columnsOf(args.table, args.output, args.vectors, args.order, args.group);
  const totals = new Map<string, number>();
  const rows = new Map<string, Row>();
  for (const leg of args.legs) {
    const window = Number(leg.limit ?? args.limit + (args.offset ?? 0));
    const hits: Hit[] = leg.kind === "vector"
      ? (await nearest(client, args.table, leg, leg.vector, window, columns, args.version)).map(([row, score]): Hit => [row, score])
      : await matches(client, args.table, leg, leg.text, window, columns, args.version);
    const ranked: [string, number][] = [];
    for (const [row, score] of hits) {
      if (within(score, leg.score_min, leg.score_max)) {
        const key = JSON.stringify(value(row[args.table.key]));
        if (!rows.has(key)) {
          rows.set(key, row);
        }
        ranked.push([key, score]);
      }
    }
    for (const [key, part] of contribution(args.fusion, args.k ?? 60, Number(leg.weight ?? 1), ranked)) {
      totals.set(key, (totals.get(key) ?? 0) + part);
    }
  }
  const ranking = [...totals.keys()].sort((a, b) => totals.get(b)! - totals.get(a)! || compare(value(rows.get(a)![args.table.key]), value(rows.get(b)![args.table.key])));
  const hits = ranking.map((key): Hit => [rows.get(key)!, totals.get(key)!]);
  return page(args.table, hits, columnsOf(args.table, args.output, args.vectors), args.limit, args.offset, args.score_min, args.score_max, args.order,
    args.group);
}

/** Searches from 2 * mean(positives) - mean(negatives) (mean(positives) without negatives); example ids are left out. */
export async function recommend(client: Client, args: { table: Layout; plan: Plan; positives: unknown[]; limit: number; output: string[];
  negatives?: unknown[]; lookup?: Layout; offset?: number; score_min?: number; score_max?: number; native?: boolean;
  vectors?: boolean | string[]; order?: Order; version?: unknown; group?: Group }): Promise<Row[]> {
  const source = args.lookup ?? args.table;
  const resolve = async (item: unknown): Promise<number[]> =>
    Array.isArray(item) ? item.map(Number) : ((await lookupVector(client, { table: source, column: args.plan.column, id: item })) as number[]).map(Number);
  const positive = await Promise.all(args.positives.map(resolve));
  const negative = await Promise.all((args.negatives ?? []).map(resolve));
  const mean = (vectors: number[][]) => vectors[0].map((_, i) => vectors.reduce((sum, vector) => sum + vector[i], 0) / vectors.length);
  const meanPositive = mean(positive);
  const query = negative.length ? meanPositive.map((p, i) => 2 * p - mean(negative)[i]) : meanPositive;
  const examples = new Set<string>();
  if (args.lookup === undefined) {
    for (const item of [...args.positives, ...(args.negatives ?? [])]) {
      if (!Array.isArray(item)) {
        examples.add(JSON.stringify(value(item)));
      }
    }
  }
  const columns = columnsOf(args.table, args.output, args.vectors, args.order, args.group);
  const window = (await windowOf(client, args.table, args.plan.where, args.limit, args.offset, args.group, args.version)) + examples.size;
  const hits = await nearest(client, args.table, args.plan, query, window, columns, args.version);
  const ranked = hits.filter(([row]) => !examples.has(JSON.stringify(value(row[args.table.key]))))
    .map(([row, score, distance]): Hit => [row, args.native ? distance : score]);
  return page(args.table, ranked, columnsOf(args.table, args.output, args.vectors), args.limit, args.offset, args.score_min, args.score_max, args.order,
    args.group);
}

/** Records by key, in the order of the ids; missing keys are left out. */
export async function getRows(client: Client, args: { table: Layout; ids: unknown[]; output: string[]; vectors?: boolean | string[]; where?: string; version?: unknown }): Promise<Row[]> {
  if (args.ids.length === 0) {
    return [];
  }
  const columns = columnsOf(args.table, args.output, args.vectors);
  const condition = keyList(args.table, args.ids) + (args.where ? ` AND (${args.where})` : "");
  const rows = (await (await read(client, args.table, args.version)).query().where(condition).select(columns).limit(args.ids.length).toArray()).map(plainRow);
  const found = new Map(rows.map((row) => [JSON.stringify(value(row[args.table.key])), row]));
  return args.ids.map((id) => found.get(JSON.stringify(value(keyOf(id))))).filter((row): row is Row => row !== undefined)
    .map((row) => record(args.table, row, columns));
}

export async function count(client: Client, args: { table: Layout; where?: string; version?: unknown }): Promise<number> {
  return (await read(client, args.table, args.version)).countRows(args.where);
}

/** A slice of the key space: the key's JSON text hashed with FNV-1a 32, modulo the slice count (the same in every runtime). */
function bucket(key: unknown, total: number): number {
  let hash = 0x811c9dc5;
  for (const byte of Buffer.from(JSON.stringify(value(key)), "utf8")) {
    hash = Math.imul(hash ^ byte, 0x01000193) >>> 0;
  }
  return hash % total;
}

/** Rows in key order (or the sort clauses, then the key), paged by offset and limit after the order is applied. */
export async function scroll(client: Client, args: { table: Layout; output: string[]; limit?: number; offset?: number; where?: string;
  order?: Order; vectors?: boolean | string[]; slice?: { index: number; total: number }; version?: unknown }): Promise<Row[]> {
  const columns = columnsOf(args.table, args.output, args.vectors, args.order);
  let query = (await read(client, args.table, args.version)).query();
  if (args.where) {
    query = query.where(args.where);
  }
  let rows = (await query.select(columns).toArray()).map(plainRow);
  rows.sort((a, b) => compare(value(a[args.table.key]), value(b[args.table.key])));
  rows = ordered(rows, args.order, path);
  if (args.slice !== undefined) {
    const slice = args.slice;
    rows = rows.filter((row) => bucket(row[args.table.key], Number(slice.total)) === Number(slice.index));
  }
  const start = args.offset ?? 0;
  rows = args.limit === undefined ? rows.slice(start) : rows.slice(start, start + args.limit);
  const shown = columnsOf(args.table, args.output, args.vectors);
  return rows.map((row) => record(args.table, row, shown));
}

/** A random sample of the matching records (first: the first records in key order). */
export async function sample(client: Client, args: { table: Layout; size: number; output: string[]; where?: string; first?: boolean; version?: unknown }): Promise<Row[]> {
  const columns = columnsOf(args.table, args.output, false);
  let query = (await read(client, args.table, args.version)).query();
  if (args.where) {
    query = query.where(args.where);
  }
  const rows = (await query.select(columns).toArray()).map(plainRow);
  rows.sort((a, b) => compare(value(a[args.table.key]), value(b[args.table.key])));
  const chosen = args.first ? rows.slice(0, args.size) : shuffle(rows).slice(0, args.size);
  return chosen.map((row) => record(args.table, row, columns));
}

function shuffle<T>(items: T[]): T[] {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

function similarityOf(metric: string, x: number[], y: number[]): number {
  if (metric === "cosine") {
    const norm = Math.sqrt(x.reduce((s, a) => s + a * a, 0)) * Math.sqrt(y.reduce((s, b) => s + b * b, 0));
    return norm ? x.reduce((s, a, i) => s + a * y[i], 0) / norm : 0;
  }
  if (metric === "dot") {
    return x.reduce((s, a, i) => s + a * y[i], 0);
  }
  if (metric === "hamming") {
    return -x.filter((a, i) => a !== y[i]).length;
  }
  return -Math.sqrt(x.reduce((s, a, i) => s + (a - y[i]) ** 2, 0));
}

/** A random sample with, for each sampled record, its nearest neighbours among the sample (canonical similarity). */
export async function distanceMatrix(client: Client, args: { table: Layout; plan: Plan; sample?: number; limit?: number; where?: string; version?: unknown }): Promise<Row[]> {
  let query = (await read(client, args.table, args.version)).query();
  if (args.where) {
    query = query.where(args.where);
  }
  const rows = (await query.select([args.table.key, args.plan.column]).toArray()).map(plainRow);
  const chosen = shuffle(rows).slice(0, args.sample ?? 10);
  const result = chosen.map((row) => {
    const others = chosen.filter((other) => other !== row)
      .map((other): Hit => [other, similarityOf(args.plan.metric, row[args.plan.column] as number[], other[args.plan.column] as number[])])
      .sort(byScore(args.table)).slice(0, args.limit ?? 3);
    return { id: value(row[args.table.key]), neighbours: others.map(([other, score]) => ({ id: value(other[args.table.key]), score: value(score) })) };
  });
  return result.sort((a, b) => compare(a.id, b.id));
}

export function toJson(result: unknown): string {
  return JSON.stringify(result, (_key, item: unknown) => (item === undefined ? null : typeof item === "bigint" ? Number(item) : item), 2);
}
